INSERT INTO `mail_templates` (`template_id`, `template_sysname`, `template_is_active`, `template_hints`) VALUES (2,'user_restore_password',1,'[sex_suffix_hello] - окончание обращения по полу пользователя (константы TXT_EMAIL_SUFFIX_SEX_M/F/UNKNOWN), [user_name] - имя, [user_login] - логин (e-mail), [restore_link] - ссылка для смены пароля (действует час), [site_name] - название сайта, [site_url] - адрес сайта');
INSERT INTO `mail_templates` (`template_id`, `template_sysname`, `template_is_active`, `template_hints`) VALUES (3,'feedback_form',1,'Письмо посетителю, указавшему e-mail. Доступны поля формы: [feed_author] - имя, [feed_email] - e-mail, [feed_theme] - тема, [feed_text] - сообщение. Значения не экранируются.');
INSERT INTO `mail_templates` (`template_id`, `template_sysname`, `template_is_active`, `template_hints`) VALUES (4,'feedback_form_admin',1,'Письмо получателям из справочника \"Получатели\" обратной связи. [feed_author] - имя, [feed_email] - e-mail, [feed_theme] - тема, [feed_text] - сообщение, [rcp_id] - id получателя. Значения не экранируются.');
INSERT INTO `mail_templates_translation` (`template_id`, `lang_id`, `template_name`, `template_subject`, `template_body`, `template_body_rtf`) VALUES (1,1,'Регистрация пользователя','Регистрация на сайте [site_name]','Здравствуйте, [user_name]!\n\nВы зарегистрированы на сайте [site_name] ([site_url]).\n\nЛогин: [user_login]\nПароль: [user_password]\n\nПисьмо отправлено автоматически, отвечать на него не нужно.','<p>Здравствуйте, [user_name]!</p>\n<p>Вы зарегистрированы на сайте <a href=\"[site_url]\">[site_name]</a>.</p>\n<p>Логин: <strong>[user_login]</strong><br>Пароль: <strong>[user_password]</strong></p>\n<p>Письмо отправлено автоматически, отвечать на него не нужно.</p>');
INSERT INTO `mail_templates_translation` (`template_id`, `lang_id`, `template_name`, `template_subject`, `template_body`, `template_body_rtf`) VALUES (1,2,'Реєстрація користувача','Реєстрація на сайті [site_name]','Вітаємо, [user_name]!\n\nВи зареєстровані на сайті [site_name] ([site_url]).\n\nЛогін: [user_login]\nПароль: [user_password]\n\nЛист надіслано автоматично, відповідати на нього не потрібно.','<p>Вітаємо, [user_name]!</p>\n<p>Ви зареєстровані на сайті <a href=\"[site_url]\">[site_name]</a>.</p>\n<p>Логін: <strong>[user_login]</strong><br>Пароль: <strong>[user_password]</strong></p>\n<p>Лист надіслано автоматично, відповідати на нього не потрібно.</p>');
INSERT INTO `mail_templates_translation` (`template_id`, `lang_id`, `template_name`, `template_subject`, `template_body`, `template_body_rtf`) VALUES (2,1,'Восстановление пароля','Смена пароля на сайте [site_name]','Уважаем[sex_suffix_hello] [user_name]!\n\nДля учётной записи [user_login] на сайте [site_name] ([site_url]) запрошена смена пароля.\nЧтобы задать новый пароль, перейдите по ссылке (она действует один час):\n[restore_link]\n\nЕсли вы не запрашивали смену пароля, просто проигнорируйте это письмо: пароль останется прежним.','<p>Уважаем[sex_suffix_hello] [user_name]!</p>\n<p>Для учётной записи [user_login] на сайте <a href=\"[site_url]\">[site_name]</a> запрошена смена пароля.</p>\n<p>Чтобы задать новый пароль, перейдите по ссылке (она действует один час):<br><a href=\"[restore_link]\">[restore_link]</a></p>\n<p>Если вы не запрашивали смену пароля, просто проигнорируйте это письмо: пароль останется прежним.</p>');
INSERT INTO `mail_templates_translation` (`template_id`, `lang_id`, `template_name`, `template_subject`, `template_body`, `template_body_rtf`) VALUES (2,2,'Відновлення пароля','Зміна пароля на сайті [site_name]','Шановн[sex_suffix_hello] [user_name]!\n\nДля облікового запису [user_login] на сайті [site_name] ([site_url]) запитано зміну пароля.\nЩоб задати новий пароль, перейдіть за посиланням (воно дійсне одну годину):\n[restore_link]\n\nЯкщо ви не запитували зміну пароля, просто проігноруйте цей лист: пароль залишиться попереднім.','<p>Шановн[sex_suffix_hello] [user_name]!</p>\n<p>Для облікового запису [user_login] на сайті <a href=\"[site_url]\">[site_name]</a> запитано зміну пароля.</p>\n<p>Щоб задати новий пароль, перейдіть за посиланням (воно дійсне одну годину):<br><a href=\"[restore_link]\">[restore_link]</a></p>\n<p>Якщо ви не запитували зміну пароля, просто проігноруйте цей лист: пароль залишиться попереднім.</p>');
INSERT INTO `mail_templates_translation` (`template_id`, `lang_id`, `template_name`, `template_subject`, `template_body`, `template_body_rtf`) VALUES (3,1,'Обратная связь: подтверждение посетителю','Ваше сообщение получено','Спасибо за ваше сообщение. Вскоре оно будет рассмотрено.','<p>Спасибо за ваше сообщение. Вскоре оно будет рассмотрено.</p>');
INSERT INTO `mail_templates_translation` (`template_id`, `lang_id`, `template_name`, `template_subject`, `template_body`, `template_body_rtf`) VALUES (3,2,'Зворотний зв\'язок: підтвердження відвідувачу','Ваше повідомлення отримано','Дякуємо за ваше повідомлення. Незабаром його буде розглянуто.','<p>Дякуємо за ваше повідомлення. Незабаром його буде розглянуто.</p>');
INSERT INTO `mail_templates_translation` (`template_id`, `lang_id`, `template_name`, `template_subject`, `template_body`, `template_body_rtf`) VALUES (4,1,'Обратная связь: уведомление получателю','Сообщение с сайта: [feed_theme]','Новое сообщение из формы обратной связи.\n\nИмя: [feed_author]\nE-mail: [feed_email]\nТема: [feed_theme]\n\n[feed_text]','<p>Новое сообщение из формы обратной связи.</p>\n<p>Имя: [feed_author]<br>E-mail: [feed_email]<br>Тема: [feed_theme]</p>\n<p>[feed_text]</p>');
INSERT INTO `mail_templates_translation` (`template_id`, `lang_id`, `template_name`, `template_subject`, `template_body`, `template_body_rtf`) VALUES (4,2,'Зворотний зв\'язок: сповіщення отримувачу','Повідомлення з сайту: [feed_theme]','Нове повідомлення з форми зворотного зв\'язку.\n\nІм\'я: [feed_author]\nE-mail: [feed_email]\nТема: [feed_theme]\n\n[feed_text]','<p>Нове повідомлення з форми зворотного зв\'язку.</p>\n<p>Ім\'я: [feed_author]<br>E-mail: [feed_email]<br>Тема: [feed_theme]</p>\n<p>[feed_text]</p>');
